    void testFingers(){SystemClock.sleep(500);main(()->{NotesView v=a.canvas;int before=v.page.strokes.size();float tx=v.tx;long t=SystemClock.uptimeMillis();finger(0,t,new float[]{500},new float[]{500});finger(2,t+40,new float[]{530},new float[]{520});finger(1,t+80,new float[]{530},new float[]{520});check(v.page.strokes.size()==before,"finger does not draw");check(v.tx!=tx,"finger pans");t+=150;finger(0,t,new float[]{500},new float[]{500});finger(MotionEvent.ACTION_POINTER_DOWN|(1<<8),t+10,new float[]{500,650},new float[]{500,500});finger(MotionEvent.ACTION_POINTER_UP|(1<<8),t+70,new float[]{500,650},new float[]{500,500});finger(1,t+90,new float[]{500},new float[]{500});check(v.page.strokes.size()==before-1,"two-finger tap undoes");v.redo();v.resetView();});pass("finger navigation and two-finger undo");}
