    void testPages(){main(()->{a.addPage();check(a.current.pages.size()==2&&a.current.current==1,"page added");a.page(-1);check(a.current.current==0,"previous page");a.canvas.setTool("hand");NotesView v=a.canvas;long t=SystemClock.uptimeMillis();MotionEvent down=event(0,t,t,new float[]{v.getWidth()*.7f},new float[]{v.getHeight()*.5f},new int[]{2},new float[]{.5f});v.onTouchEvent(down);down.recycle();MotionEvent up=event(1,t,t+100,new float[]{v.getWidth()*.2f},new float[]{v.getHeight()*.5f},new int[]{2},new float[]{.5f});v.onTouchEvent(up);up.recycle();check(a.current.current==1,"stylus swipe page");a.page(-1);});pass("page creation and stylus page swipe");}
    void testTaps(){final int[] counts=new int[2];PenGestures.Actions actions=new PenGestures.Actions(){public void single(){counts[0]++;}public void doubleTap(){counts[1]++;}};PenGestures g=new PenGestures(300);g.tap(1000,actions);g.flush(1200,actions);check(counts[0]==0,"single waits");g.tap(1250,actions);g.flush(2000,actions);check(counts[1]==1&&counts[0]==0,"double excludes single");g.tap(2200,actions);g.flush(2501,actions);check(counts[0]==1,"single fires");g.tap(3000,actions);g.cancel();g.flush(4000,actions);check(counts[0]==1,"pause cancels pending tap");main(()->{a.canvas.setTool("brush");a.canvas.toggleEraser();check(a.canvas.tool.equals("eraser"),"double eraser");a.canvas.toggleEraser();check(a.canvas.tool.equals("brush"),"restore previous tool");a.canvas.showPalette();check(a.canvas.radial,"radial palette");a.canvas.showPalette();check(!a.canvas.radial,"radial dismiss");});pass("single/double hardware gesture arbitration and palette");}
    void testIo()throws Exception{
        AtomicReference<Ink.Doc> snapshot=new AtomicReference<>();main(()->{a.saveNow();snapshot.set(a.current.copy());});Ink.Doc doc=snapshot.get();a.store.io.submit(()->{}).get();
        Ink.Doc parsed=Ink.Doc.parse(new JSONObject(doc.json().toString()));check(parsed.pages.size()==2,"JSON pages roundtrip");check(parsed.pages.get(0).strokes.size()==9,"JSON strokes roundtrip");
        File pdf=new File(out,"roundtrip.pdf"),png=new File(out,"page.png"),zip=new File(out,"roundtrip.folio");
        try(OutputStream stream=new FileOutputStream(pdf)){a.store.exportPdf(doc,stream);}check(pdf.length()>1000,"PDF written");
        try(OutputStream stream=new FileOutputStream(png)){a.store.exportPng(doc.pages.get(0),stream);}check(png.length()>1000,"PNG written");
        try(OutputStream stream=new FileOutputStream(zip)){a.store.exportArchive(doc,stream);}Ink.Doc imported=a.store.importFile(Uri.fromFile(zip),"application/octet-stream",zip.getName());check(imported.pages.get(0).strokes.size()==9,"Folio archive roundtrip");a.store.delete(imported);
        Ink.Doc pdfDoc=a.store.importFile(Uri.fromFile(pdf),"application/pdf",pdf.getName());check(pdfDoc.pages.size()==2,"PDF page import");check(!pdfDoc.pages.get(0).background.isEmpty(),"PDF background stored");a.store.delete(pdfDoc);
        Ink.Doc image=a.store.importFile(Uri.fromFile(png),"image/png",png.getName());check(image.pages.size()==1&&!image.page().background.isEmpty(),"PNG import");File withAsset=new File(out,"image.folio");try(OutputStream stream=new FileOutputStream(withAsset)){a.store.exportArchive(image,stream);}Ink.Doc assetCopy=a.store.importFile(Uri.fromFile(withAsset),"application/octet-stream","image.folio");check(!assetCopy.page().background.equals(image.page().background),"archive assigns isolated resource IDs");check(a.store.asset(assetCopy.page().background).isFile(),"archive resource exists");a.store.delete(image);a.store.delete(assetCopy);
        JSONObject invalid=new JSONObject(doc.json().toString());invalid.getJSONArray("pages").getJSONObject(0).put("background","../bad.png");boolean rejected=false;try{Ink.Doc.parse(invalid);}catch(JSONException e){rejected=true;}check(rejected,"path traversal rejected");
        File badZip=new File(out,"bad.folio");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(badZip))){z.putNextEntry(new ZipEntry("../bad.png"));z.write(new byte[]{1,2,3});z.closeEntry();}rejected=false;try{a.store.importFile(Uri.fromFile(badZip),"application/octet-stream","bad.folio");}catch(IOException e){rejected=true;}check(rejected,"unsafe ZIP rejected");pass("atomic save, PDF/PNG/Folio export and import, unsafe archives");
    }
    void testHardware(){main(()->{
        a.resumed=true;a.focused=true;a.actions.cancel();a.actions.save("squeeze",Arrays.asList("cycle"));a.actions.save("double_squeeze",Arrays.asList("palette"));a.actions.save("hold",Arrays.asList("none"));
        a.canvas.setTool("pencil");a.hardware(SystemClock.uptimeMillis(),96,1);check(a.canvas.tool.equals("eraser"),"physical double-tap code toggles eraser");a.hardware(SystemClock.uptimeMillis()+600,96,1);check(a.canvas.tool.equals("pencil"),"physical double-tap returns selected tool");
        long now=SystemClock.uptimeMillis();String before=a.canvas.tool;a.hardware(now,189,1);a.hardware(now+30,189,0);check(!a.canvas.radial&&a.canvas.tool.equals(before),"single squeeze waits without opening menu");a.actions.squeezes.singleTimeout(a.actions::run);check(!a.canvas.tool.equals(before)&&!a.canvas.radial,"single squeeze cycles tool");a.actions.cancel();before=a.canvas.tool;
        a.hardware(now+1000,189,1);a.hardware(now+1030,189,0);a.hardware(now+1150,189,1);check(a.canvas.radial&&a.canvas.tool.equals(before),"second squeeze opens radial without cycling tool");a.hardware(now+1600,189,0);a.actions.squeezes.singleTimeout(a.actions::run);check(a.canvas.tool.equals(before),"long second release cannot emit single");a.actions.cancel();a.canvas.closePalette();
        a.hardware(now+2000,81,1);check(a.current.current==1,"physical swipe code advances page");a.hardware(now+2500,73,1);check(a.current.current==0,"physical swipe code goes back");a.canvas.setTool("pen");a.canvas.width=4;a.canvas.setTool("brush");a.canvas.width=17;a.canvas.setTool("pen");check(a.canvas.width==4,"tool remembers independent width");a.canvas.setTool("brush");check(a.canvas.width==17,"brush remembers independent width");
    });pass("Focus Pen Pro tap/squeeze/swipe routing, exclusive single/double squeeze actions and per-tool widths");}
    void testLifecycle()throws Exception{main(()->{a.resumed=true;a.focused=true;check(a.penActive(),"foreground pen lease");a.onWindowFocusChanged(false);check(!a.penActive(),"focus loss disables suppression");a.onWindowFocusChanged(true);a.saveNow();});a.store.io.submit(()->{}).get();ArrayList<Ink.Doc> loaded=a.store.load();boolean found=false;for(Ink.Doc d:loaded)if(d.id.equals(testDoc.id)){found=true;check(d.pages.get(0).strokes.size()==9,"reloaded ink");check(d.pages.size()==2,"reloaded pages");}check(found,"saved notebook reopens");pass("foreground lease release and persisted notebook reload");}
    void testDrawingAids(){
        Ink.Doc guides=new Ink.Doc();temporaryDocs.add(guides);guides.title="Временная проверка чертёжной вкладки";
        main(()->{a.open(guides);a.canvas.setGuide("none");a.canvas.setTool("brush");});waitForIdleSync();
        main(()->{
            NotesView v=a.canvas;v.autoShapes=false;v.edgeSwipe=false;v.rotationEnabled=false;v.pressure=true;v.fit=v.zoom=1;v.tx=v.ty=0;
            GuideStudio.select(a,"ruler",false);RulerOverlay.place(v);String ink=v.tool;
            check(a.toolsTab.equals("guides")&&v.guideMode.equals("ruler")&&ink.equals("brush"),"guide tab selects ruler independently of ink");
            int tiles=0;for(int i=0;i<a.tools.getChildCount();i++)if(a.tools.getChildAt(i) instanceof ToolArt.Tile){tiles++;check(GuideTools.auxiliary(((ToolArt.Tile)a.tools.getChildAt(i)).tool),"drawing tab contains drawing aids");}check(tiles==2,"ruler and compass in separate tab");
            for(String name:new String[]{"line","compass"}){
                ToolArt.Tile tile=null;for(int j=0;j<a.tools.getChildCount();j++)if(a.tools.getChildAt(j) instanceof ToolArt.Tile&&((ToolArt.Tile)a.tools.getChildAt(j)).tool.equals(name))tile=(ToolArt.Tile)a.tools.getChildAt(j);
                check(tile!=null&&tile.isLongClickable(),"aid has a settings hold action");v.setGuide("none");tile.performClick();check(v.guideMode.equals(GuideTools.mode(name))&&v.tool.equals(ink),"first click activates aid without replacing ink");tile.performClick();check(v.guideMode.equals("none")&&v.tool.equals(ink),"second click removes aid without replacing ink");
            }
            v.setGuide("ruler");
            View penTab=a.body.findViewWithTag("tool_tab_ink");check(penTab!=null&&penTab.performClick(),"fixed pen tab switches group");check(a.toolsTab.equals("ink")&&v.guideMode.equals("ruler"),"switching tabs retains ruler");
            for(String name:ToolSettings.visible(a))check(!GuideTools.auxiliary(name),"aids excluded from configurable pen list");for(String name:v.radialTools)check(!GuideTools.auxiliary(name),"aids excluded from squeeze palette");
            v.ruler.x=v.getWidth()/v.dp(1)/2;v.ruler.y=v.getHeight()/v.dp(1)*.55f;v.ruler.degrees=0;v.ruler.placed=true;
            float sx=v.ruler.x,sy=v.ruler.y,capture=RulerOverlay.captureDistance(v);long t=SystemClock.uptimeMillis();
            for(float edge:new float[]{0,RulerGeometry.THICKNESS})for(String tool:new String[]{"pen","fountain","marker","brush"}){
                v.setTool(tool);v.activeColor(0xffab3456);v.width=7;int count=v.page.strokes.size();
                pen(0,t,v.px((sx-85)*v.dp(1)),v.py((sy+edge-capture*.4f)*v.dp(1)),.2f);pen(2,t+10,v.px((sx+85)*v.dp(1)),v.py((sy+edge+capture*.4f)*v.dp(1)),.8f);pen(1,t+20,v.px((sx+100)*v.dp(1)),v.py((sy+edge+capture*.5f)*v.dp(1)),1);t+=30;
                check(v.page.strokes.size()==count+1,"guided ink committed: "+tool);Ink.Stroke stroke=v.page.strokes.get(count);check(stroke.tool.equals(tool)&&stroke.width==7&&stroke.color==0xffab3456,"ruler retains chosen tool, width and color");
                for(Ink.Pt point:stroke.points)check(Math.abs(v.ruler.localY((point.x*v.scale()+v.tx)/v.dp(1),(point.y*v.scale()+v.ty)/v.dp(1))-edge)<.01,"every ruler ink point lies on selected upper/lower edge");check(stroke.points.get(0).p==.2f&&stroke.points.get(stroke.points.size()-1).p>.8f,"ruler retains variable pressure through ordinary ink smoothing");
            }
            for(float edge:new float[]{0,RulerGeometry.THICKNESS}){
                int count=v.page.strokes.size();float side=edge==0?-1:1,other=edge==0?RulerGeometry.THICKNESS:0;
                pen(0,t,v.px((sx-50)*v.dp(1)),v.py((sy+edge+side*80)*v.dp(1)),.5f);check(Float.isNaN(v.guideEdge),"stroke may begin far from ruler");
                Ink.Pt first=v.draft.points.get(0);pen(2,t+10,v.px(sx*v.dp(1)),v.py((sy+edge+side*capture*.8f)*v.dp(1)),.7f);check(v.guideEdge==edge,"ongoing stroke captures ruler within two millimeters");
                Ink.Pt snapped=v.draft.points.get(v.draft.points.size()-1);check(Math.abs(v.ruler.localY((snapped.x*v.scale()+v.tx)/v.dp(1),(snapped.y*v.scale()+v.ty)/v.dp(1))-edge)<.01,"first captured sample lies exactly on edge despite ordinary smoothing");check(v.draft.points.get(0)==first,"capture never rewrites existing freehand ink");
                pen(2,t+20,v.px((sx+30)*v.dp(1)),v.py((sy+edge+side*capture*1.5f)*v.dp(1)),.7f);check(Float.isNaN(v.guideEdge),"moving away releases without lifting");
                pen(2,t+30,v.px((sx+60)*v.dp(1)),v.py((sy+other)*v.dp(1)),.7f);check(v.guideEdge==other,"same stroke captures opposite edge");
                pen(1,t+40,v.px((sx+90)*v.dp(1)),v.py((sy+other)*v.dp(1)),.7f);t+=50;check(v.page.strokes.size()==count+1&&v.guideStroke==0&&Float.isNaN(v.guideEdge),"one history stroke commits and releases magnet state");
            }
            v.setTool("eraser");check(v.guideMode.equals("ruler")&&v.ruler.x==sx&&v.ruler.y==sy,"eraser selection does not remove or move ruler");v.setTool("hand");v.lastPen=-10000;
            finger(0,t,new float[]{20},new float[]{30});finger(2,t+10,new float[]{65},new float[]{55});finger(1,t+20,new float[]{65},new float[]{55});
            check(v.tx==45&&v.ty==25,"finger pans document beneath ruler");check(v.ruler.x==sx&&v.ruler.y==sy,"document pan leaves ruler fixed");
            finger(0,t+30,new float[]{100},new float[]{40});finger(5|(1<<8),t+40,new float[]{100,200},new float[]{40,40});finger(2,t+50,new float[]{50,250},new float[]{40,40});finger(6|(1<<8),t+60,new float[]{50,250},new float[]{40,40});finger(1,t+70,new float[]{50},new float[]{40});check(v.zoom>1.5f,"fingers zoom document away from ruler body");check(v.ruler.x==sx&&v.ruler.y==sy,"document zoom leaves ruler fixed");
            float d=v.dp(1),cx=sx*d,cy=(sy+20)*d;float oldZoom=v.zoom,oldTx=v.tx;
            finger(0,t+80,new float[]{cx-50*d},new float[]{cy});finger(5|(1<<8),t+90,new float[]{cx-50*d,cx+50*d},new float[]{cy,cy});finger(2,t+100,new float[]{cx+10*d,cx+10*d},new float[]{cy-40*d,cy+60*d});
            check(Math.abs(v.ruler.degrees-90)<.01,"two fingers rotate ruler to angle magnet");check(v.zoom==oldZoom&&v.tx==oldTx,"ruler gesture does not pan or zoom document");
            finger(6|(1<<8),t+110,new float[]{cx+10*d,cx+10*d},new float[]{cy-40*d,cy+60*d});finger(1,t+120,new float[]{cx+10*d},new float[]{cy-40*d});check(!v.rulerManipulation.active,"ruler gesture ends cleanly");
            v.setTool("brush");v.cycleTools=new String[]{"line","compass","pen","brush"};a.actions.command("cycle");check(v.tool.equals("pen")&&v.guideMode.equals("ruler"),"squeeze cycle changes ink without activating an aid");a.actions.command("tool:compass");check(v.guideMode.equals("ruler")&&v.tool.equals("pen"),"old explicit gesture cannot activate compass");
            a.savePenPrefs();v.setTool("marker");v.setGuide("none");v.tool="eraser";v.guideMode="compass";a.applyPenPrefs();check(v.tool.equals("marker")&&v.guideMode.equals("none"),"saved independent state reloads");
            a.prefs.edit().putString("tool","line").remove("active_guide").putString("last_ink_tool","brush").commit();a.applyPenPrefs();check(v.tool.equals("brush")&&v.guideMode.equals("ruler"),"legacy ruler selection migrates to independent guide");
            v.setGuide("none");v.setTool("pen");a.toolsTab="ink";a.refreshTools();
        });pass("native independent guide tabs, infinite screen ruler, mid-stroke two-millimeter top/bottom capture and release, click toggles/hold binding, selected ink/pressure, pan/zoom, two-finger rotation, squeeze exclusion and legacy preference migration; Android execution required");
    }
    View description(View root,String text){if(text.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){View found=description(group.getChildAt(i),text);if(found!=null)return found;}}return null;}
    void testCanvasDefaults(){
        final Studio.Sheet[] sheet={null};final Ink.Page[] original={null};
        main(()->{
            CanvasDefaults.reset(a.prefs);Ink.Page style=new Ink.Page();style.infinite=false;style.width=900;style.height=1400;style.paper=0xfffffaf0;style.lines=0x4d112233;style.pattern="lined";style.spacing=48;style.background="test.png";style.strokes.add(new Ink.Stroke());CanvasDefaults.save(a.prefs,style);
            original[0]=a.canvas.page;Ink.Doc fresh=a.blankNotebook("");temporaryDocs.add(fresh);check(fresh.page().width==900&&fresh.page().height==1400&&!fresh.page().infinite,"new notebook factory uses saved dimensions");check(fresh.page().paper==style.paper&&fresh.page().lines==style.lines&&fresh.page().pattern.equals("lined")&&fresh.page().spacing==48,"new notebook inherits saved paper and markup");check(fresh.page().background.isEmpty()&&fresh.page().strokes.isEmpty(),"saved defaults never copy source image or ink");
            sheet[0]=CanvasDefaultsStudio.show(a);View dots=description(sheet[0].spec.content,"Разметка: Точки");check(dots!=null&&dots.performClick(),"defaults draft exposes shared markup controls");check(CanvasDefaults.read(a.prefs).pattern.equals("lined"),"editing draft is transactional before save");sheet[0].dismissNow();check(a.canvas.page==original[0],"cancelled defaults leave current canvas intact");a.library();
            sheet[0]=CanvasDefaultsStudio.show(a);check(a.canvas==null,"defaults editor also opens from library without a canvas");dots=description(sheet[0].spec.content,"Разметка: Точки");dots.performClick();sheet[0].getButton(-1).performClick();check(CanvasDefaults.read(a.prefs).pattern.equals("dots"),"save stores draft settings");
        });waitForIdleSync();SystemClock.sleep(240);
        main(()->{
            Ink.Doc fresh=a.blankNotebook("Проверка стандартного холста");temporaryDocs.add(fresh);check(fresh.page().pattern.equals("dots"),"subsequent notebook uses updated defaults");a.open(fresh);a.addPage();check(a.canvas.page.pattern.equals("dots")&&a.canvas.page.width==900,"additional pages inherit their notebook paper");CanvasDefaults.reset(a.prefs);Ink.Doc reset=a.blankNotebook("Сброс стандартного холста");temporaryDocs.add(reset);check(reset.page().infinite&&reset.page().paper==0xffffffff&&reset.page().pattern.equals("grid"),"reset restores original blank-canvas defaults");check(fresh.page().pattern.equals("dots")&&!fresh.page().infinite,"reset does not alter existing notebooks");
        });pass("native persisted canvas defaults, creation factory, isolated draft/cancel/save, library access, new page inheritance and scoped reset; compiled, Android execution required");
    }
