    int inkPixels(Bitmap b){int count=0;for(int y=0;y<b.getHeight();y++)for(int x=0;x<b.getWidth();x++)if(Color.alpha(b.getPixel(x,y))>200)count++;return count;}
    Bitmap rendered(Ink.Stroke s){Bitmap bitmap=Bitmap.createBitmap(1300,180,Bitmap.Config.ARGB_8888);InkRenderer.stroke(new Canvas(bitmap),s);return bitmap;}
    void testRefinedInk()throws Exception{
        Ink.Stroke low=horizontal(40,90,1240);low.width=12;low.points.clear();low.points.add(new Ink.Pt(40,90,.08f,1.1f,2.1f,-.7f));low.points.add(new Ink.Pt(1240,90,.08f,.1f,.2f,.8f));Ink.Stroke high=low.copy();high.points.clear();for(Ink.Pt point:low.points)high.points.add(new Ink.Pt(point.x,point.y,1,point.tilt,point.angle,point.azimuth));
        Bitmap b=rendered(low),h=rendered(high);check(b.sameAs(h),"ballpoint raster ignores pressure, tilt and roll");b.recycle();h.recycle();
        low.tool=high.tool="fountain";b=rendered(low);h=rendered(high);check(inkPixels(h)>inkPixels(b)*1.8,"fountain raster responds to pressure");b.recycle();h.recycle();
        for(String tool:new String[]{"fountain","brush","pencil"}){low.tool=tool;low.width=3;b=rendered(low);for(int x=41;x<1240;x++)check(Color.alpha(b.getPixel(x,90))>0,"sparse native ribbon stays connected "+tool);b.recycle();}
        Ink.Stroke dot=new Ink.Stroke();dot.width=12;dot.points.add(new Ink.Pt(50,50,.1f,0,0));dot.points.add(new Ink.Pt(50,50,1,1,2));b=rendered(dot);check(Color.alpha(b.getPixel(50,50))==255,"stationary ballpoint remains visible");b.recycle();dot.tool="fountain";b=rendered(dot);check(Color.alpha(b.getPixel(50,44))>0&&Color.alpha(b.getPixel(44,50))>0,"fountain dot is round");b.recycle();
        Ink.Stroke parsed=Ink.Stroke.parse(new JSONObject(low.json().toString()));check(Math.abs(parsed.points.get(0).azimuth+.7f)<.001,"azimuth survives JSON");JSONObject legacy=low.json();legacy.remove("azimuths");parsed=Ink.Stroke.parse(legacy);check(parsed.points.get(0).azimuth==parsed.points.get(0).angle,"legacy bearing fallback");JSONObject bad=low.json();bad.put("azimuths",new JSONArray());boolean rejected=false;try{Ink.Stroke.parse(bad);}catch(JSONException expected){rejected=true;}check(rejected,"incomplete bearing array rejected");pass("refined native pen raster, sparse brush ribbons and tilt bearing persistence");
    }
