        SystemClock.sleep(160);
        main(()->{check(popup[0].card.getWidth()<=a.dp(303),"eraser inspector also compact");check(popup[0].openingFrames==0&&popup[0].card.getScaleX()==1,"local animation preference can disable the effect");popup[0].dismissNow();a.prefs.edit().putBoolean("card_motion",true).commit();});
        pass("reference popover motion, relayout regression, glass, frame cleanup and local animation preference");
