    void testLaserLight()throws Exception{
        Ink.Doc light=new Ink.Doc();light.page().infinite=false;temporaryDocs.add(light);light.title="Временная проверка лазера";light.page().paper=Color.WHITE;light.page().pattern="blank";
        main(()->{a.open(light);NotesView v=a.canvas;v.edgeSwipe=false;v.showHover=true;v.setTool("laser");v.laser.mode(false);long t=SystemClock.uptimeMillis();pen(0,t,200,350,1);pen(2,t+30,500,350,1);pen(1,t+60,700,350,1);check(v.draft==null&&v.laser.pointCount()==0,"laser point creates no ink path");check(v.page.strokes.isEmpty()&&!v.history().canUndo()&&a.revision==0,"laser leaves document and undo history unchanged");
            LaserEffect effect=new LaserEffect();effect.diameter=8;effect.down(80,80,1000);effect.move(700,80,1100);LaserPainter renderer=new LaserPainter();Bitmap bitmap=Bitmap.createBitmap(800,200,Bitmap.Config.ARGB_8888);renderer.draw(new Canvas(bitmap),effect,1100,1);check(Color.alpha(bitmap.getPixel(400,80))==0,"native point draws no connecting line");check(Color.alpha(bitmap.getPixel(700,80))>240,"native point has bright centre");check(Color.green(bitmap.getPixel(700,80))>200,"native laser centre is white hot");check(Color.alpha(bitmap.getPixel(709,80))>0,"native laser has soft bloom");bitmap.eraseColor(Color.TRANSPARENT);effect.release(1200);renderer.draw(new Canvas(bitmap),effect,1500,1);check(inkPixels(bitmap)==0,"native point fades to transparent");bitmap.recycle();
            int ink=v.color;v.activeColor(0xff399fff);a.savePenPrefs();check(v.color==ink&&a.prefs.getInt("laser_color",0)==0xff399fff,"laser color persists without changing pen ink");v.laser.mode(true);t=SystemClock.uptimeMillis();pen(0,t,220,500,1);pen(2,t+30,600,500,1);check(v.laser.pointCount()>1,"trail captures transient samples");pen(3,t+50,600,500,1);check(!v.laser.active(SystemClock.uptimeMillis())&&v.page.strokes.isEmpty(),"cancel clears trail without document edits");hover(9,400,700);check(v.laser.hovering,"laser glows on hover");a.onWindowFocusChanged(false);check(!v.laser.active(SystemClock.uptimeMillis()),"focus loss clears light and frame loop");a.onWindowFocusChanged(true);v.fingerDraw=true;v.lastPen=-10000;finger(0,t+100,new float[]{500},new float[]{600});check(v.laser.touching,"enabled finger input can point");finger(MotionEvent.ACTION_POINTER_DOWN|(1<<8),t+110,new float[]{500,650},new float[]{600,600});check(!v.laser.touching,"second finger cancels laser before navigation");v.finishGesture(true);a.saveNow();});
        a.store.io.submit(()->{}).get();check(!light.json().toString().contains("\"tool\":\"laser\""),"Folio JSON contains no laser overlay");File exported=new File(out,"laser-clean-export.png");try(OutputStream stream=new FileOutputStream(exported)){a.store.exportPng(light.page(),stream);}Bitmap png=BitmapFactory.decodeFile(exported.toString());check(png.getPixel(png.getWidth()/2,png.getHeight()/2)==Color.WHITE,"PNG export omits transient laser");png.recycle();pass("native laser glow, no line in dot mode, cancellation, history, preferences, hover, focus and clean export");
    }
